steps.data:
/* Tax categories prototype: reviewer guide. Matches the mockups in the requirements doc
   (purple dashed outline, purple "New" badge). */
:root {
	--wctc-new: #7a4fc9;
	--wctc-new-line: #8a63d2;
	--wctc-new-tint: #f5f1fc;
	--wctc-tip-bg: #1d2327;
	--wctc-tip-fg: #ffffff;
}

/* Outline on every new field, column header or section. */
.wctc-new {
	outline: 1.5px dashed var(--wctc-new-line) !important;
	outline-offset: 2px;
	border-radius: 4px;
}
tr.wctc-new { outline-offset: -2px; }
th.wctc-new { outline-offset: -3px; }
.wctc-touring { outline: 2px solid var(--wctc-new) !important; outline-offset: 3px; }

/* The columns this plugin adds (Products list, Categories list) have multi-word labels
   ("Tax category") plus a New badge. Without a min-width, WordPress's auto-sized wp-list-table
   can squeeze the TH to one letter per line; with pure `nowrap`, the text overflows and visually
   overlaps the neighbouring column. A fixed width lets the words break on the space between
   them, keeping the header stable regardless of neighbour widths. */
th.column-wctc, th.manage-column.column-wctc {
	min-width: 8em;
	width: 8em;
	word-wrap: normal;
	overflow-wrap: break-word;
}
th.column-wctc .wctc-badge { display: inline-block; margin-top: 2px; }

/* "New" badge with a tooltip on hover or keyboard focus. */
.wctc-badge {
	position: relative;
	display: inline-block;
	margin-left: 6px;
	padding: 0 7px;
	border-radius: 9px;
	background: var(--wctc-new);
	color: #fff;
	font-size: 10.5px;
	font-weight: 600;
	line-height: 17px;
	letter-spacing: .02em;
	vertical-align: 1px;
	cursor: help;
	white-space: nowrap;
	text-transform: none;
}
.wctc-item-notes > .wctc-badge { margin: 0 0 4px; }
.wctc-badge-static { cursor: default; margin-left: 0; }
.wctc-badge:focus-visible { outline: 2px solid var(--wctc-new); outline-offset: 2px; }
.wctc-badge:not(.wctc-badge-static):hover::after,
.wctc-badge:not(.wctc-badge-static):focus::after {
	content: attr(data-tip);
	position: absolute;
	z-index: 100000;
	left: 0;
	top: calc(100% + 8px);
	width: 280px;
	padding: 8px 10px;
	border-radius: 6px;
	background: var(--wctc-tip-bg);
	color: var(--wctc-tip-fg);
	font-size: 12.5px;
	font-weight: 400;
	line-height: 1.45;
	letter-spacing: 0;
	white-space: normal;
	box-shadow: 0 4px 14px rgba(0, 0, 0, .18);
}
.wctc-badge:not(.wctc-badge-static):hover::before,
.wctc-badge:not(.wctc-badge-static):focus::before {
	content: "";
	position: absolute;
	z-index: 100001;
	left: 10px;
	top: calc(100% + 3px);
	border: 5px solid transparent;
	border-bottom-color: var(--wctc-tip-bg);
}
/* Headers near the right edge open the tooltip leftwards. */
th.column-wctc .wctc-badge:hover::after,
th.column-wctc .wctc-badge:focus::after { left: auto; right: 0; }

/* "What's new on this screen" banner. */
.wctc-banner {
	margin: 12px 0 16px;
	padding: 12px 16px;
	max-width: 980px;
	background: var(--wctc-new-tint);
	border: 1.5px dashed var(--wctc-new-line);
	border-radius: 6px;
	color: #1d2327;
}
.wctc-banner-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
.wctc-banner-title { font-size: 14px; }
.wctc-banner-actions { margin-left: auto; display: inline-flex; align-items: center; gap: 12px; }
.wctc-banner .button-primary { background: var(--wctc-new); border-color: var(--wctc-new); }
.wctc-banner .button-primary:hover, .wctc-banner .button-primary:focus { background: #6640b8; border-color: #6640b8; }
.wctc-banner .button-link { color: var(--wctc-new); }
.wctc-banner-body { margin-top: 10px; max-width: 760px; }
.wctc-banner-body p { margin: 0 0 8px; }
.wctc-banner-body h4 { margin: 12px 0 6px; font-size: 13px; }
.wctc-banner-body ol { margin: 0 0 10px 20px; }
.wctc-banner-body li { margin-bottom: 4px; }
.wctc-banner.is-collapsed .wctc-banner-body { display: none; }
.wctc-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; color: #50575e; font-size: 12.5px; }
.wctc-legend-swatch { width: 22px; height: 12px; border: 1.5px dashed var(--wctc-new-line); border-radius: 3px; }

/* Tour pointers. */
.wctc-pointer .wp-pointer-content h3 { background: var(--wctc-new); border-color: var(--wctc-new); }
.wctc-pointer .wp-pointer-content h3::before { color: var(--wctc-new); }
.wctc-pointer.wp-pointer-top .wp-pointer-arrow { border-bottom-color: var(--wctc-new); }
.wctc-pointer.wp-pointer-top .wp-pointer-arrow-inner { border-bottom-color: var(--wctc-new); }
.wctc-step { float: right; font-weight: 400; font-size: 12px; opacity: .85; margin-right: 4px; }
.wctc-tour-buttons { display: flex; align-items: center; gap: 8px; width: 100%; }
.wctc-tour-buttons .wctc-tour-close { margin-right: auto; color: #50575e; }
.wctc-pointer .button-primary { background: var(--wctc-new); border-color: var(--wctc-new); }

@media (prefers-reduced-motion: reduce) {
	.wctc-pointer { transition: none !important; }
}

/**
 * Tax categories prototype: reviewer guide.
 * Marks new fields (dashed outline + "New" badge with a tooltip), shows a "What's new" banner with
 * how-to steps, and runs a guided tour of the new fields using WordPress's built-in pointers.
 */
( function ( $ ) {
	'use strict';

	var cfg = window.wctcGuide;
	if ( ! cfg || ! cfg.guide ) {
		return;
	}
	var guide = cfg.guide;
	var storeKey = 'wctc-guide-collapsed-' + cfg.key;

	function all( selector ) {
		try {
			return Array.prototype.slice.call( document.querySelectorAll( selector ) );
		} catch ( e ) {
			return []; // Browsers without :has() skip that field instead of breaking the page.
		}
	}

	function esc( text ) {
		return String( text ).replace( /[&<>"']/g, function ( c ) {
			return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ c ];
		} );
	}

	function makeBadge( tip ) {
		var badge = document.createElement( 'span' );
		badge.className = 'wctc-badge';
		badge.tabIndex = 0;
		badge.setAttribute( 'role', 'note' );
		badge.setAttribute( 'aria-label', 'New: ' + tip );
		badge.setAttribute( 'data-tip', tip );
		badge.textContent = 'New';
		return badge;
	}

	// 1. Outline every new field and put a "New" badge with a tooltip on its label.
	function decorate() {
		guide.fields.forEach( function ( field ) {
			all( field.outline ).forEach( function ( el ) {
				el.classList.add( 'wctc-new' );
			} );
			if ( false === field.badge ) {
				return;
			}
			all( field.label ).forEach( function ( el ) {
				if ( el.querySelector( ':scope > .wctc-badge' ) ) {
					return;
				}
				var badge = makeBadge( field.tip );
				if ( 'prepend' === field.badge ) {
					el.insertBefore( badge, el.firstChild );
				} else {
					el.appendChild( badge );
				}
			} );
		} );
	}

	// 2. "What's new on this screen" banner with how-to steps and a tour button.
	function banner() {
		if ( document.querySelector( '.wctc-banner' ) ) {
			return;
		}
		var collapsed = false;
		try {
			collapsed = '1' === window.localStorage.getItem( storeKey );
		} catch ( e ) {}

		var steps = guide.steps.map( function ( step ) {
			return '<li>' + step + '</li>';
		} ).join( '' );
		var html =
			'<div class="wctc-banner' + ( collapsed ? ' is-collapsed' : '' ) + '" role="region" aria-label="What\'s new on this screen">' +
				'<div class="wctc-banner-head">' +
					'<span class="wctc-badge wctc-badge-static">New</span>' +
					'<strong class="wctc-banner-title">' + esc( guide.title ) + '</strong>' +
					'<span class="wctc-banner-actions">' +
						'<button type="button" class="button button-primary wctc-tour-start">Take the tour</button>' +
						'<button type="button" class="button-link wctc-banner-toggle" aria-expanded="' + ( collapsed ? 'false' : 'true' ) + '">' + ( collapsed ? 'Show how to use it' : 'Hide' ) + '</button>' +
					'</span>' +
				'</div>' +
				'<div class="wctc-banner-body">' +
					'<p>' + esc( guide.intro ) + '</p>' +
					'<h4>How to use it</h4>' +
					'<ol>' + steps + '</ol>' +
					'<p class="wctc-legend"><span class="wctc-legend-swatch" aria-hidden="true"></span>Outlined fields are new in the tax categories prototype. Hover or tab to a <span class="wctc-badge wctc-badge-static">New</span> badge to see what it does.</p>' +
				'</div>' +
			'</div>';

		var $banner = $( html );
		var $anchor = $( '#mainform' ).first();
		if ( $anchor.length ) {
			$anchor.prepend( $banner );
		} else if ( $( 'hr.wp-header-end' ).length ) {
			$( 'hr.wp-header-end' ).first().after( $banner );
		} else {
			$( '#wpbody-content .wrap' ).first().prepend( $banner );
		}

		$banner.on( 'click', '.wctc-banner-toggle', function () {
			var isCollapsed = $banner.toggleClass( 'is-collapsed' ).hasClass( 'is-collapsed' );
			$( this ).attr( 'aria-expanded', isCollapsed ? 'false' : 'true' ).text( isCollapsed ? 'Show how to use it' : 'Hide' );
			try {
				window.localStorage.setItem( storeKey, isCollapsed ? '1' : '0' );
			} catch ( e ) {}
		} );
		$banner.on( 'click', '.wctc-tour-start', startTour );
	}

	// 3. Guided tour: one pointer per new field that is on screen.
	var current = null;

	function tourSteps() {
		var steps = [];
		guide.fields.forEach( function ( field ) {
			if ( false === field.tour ) {
				return;
			}
			var el = all( field.outline ).filter( function ( node ) {
				return node.offsetParent !== null;
			} )[ 0 ];
			if ( el ) {
				steps.push( { el: el, title: field.title, tip: field.tip } );
			}
		} );
		return steps;
	}

	function closeCurrent() {
		if ( current ) {
			try {
				current.pointer( 'close' );
				current.pointer( 'destroy' );
			} catch ( e ) {}
			current = null;
		}
		$( '.wctc-touring' ).removeClass( 'wctc-touring' );
	}

	function showStep( steps, i ) {
		closeCurrent();
		var step = steps[ i ];
		var last = i === steps.length - 1;
		step.el.scrollIntoView( { block: 'center', behavior: 'auto' } );
		step.el.classList.add( 'wctc-touring' );
		var $el = $( step.el );
		window.setTimeout( function () {
			$el.pointer( {
				pointerClass: 'wp-pointer wctc-pointer',
				content: '<h3>' + esc( step.title ) + '<span class="wctc-step">' + ( i + 1 ) + ' of ' + steps.length + '</span></h3><p>' + esc( step.tip ) + '</p>',
				position: { edge: 'top', align: 'left' },
				buttons: function () {
					var $wrap = $( '<div class="wctc-tour-buttons"></div>' );
					$( '<button type="button" class="button-link wctc-tour-close">Close tour</button>' ).on( 'click', closeCurrent ).appendTo( $wrap );
					if ( i > 0 ) {
						$( '<button type="button" class="button">Back</button>' ).on( 'click', function () {
							showStep( steps, i - 1 );
						} ).appendTo( $wrap );
					}
					$( '<button type="button" class="button button-primary">' + ( last ? 'Done' : 'Next' ) + '</button>' ).on( 'click', function () {
						if ( last ) {
							closeCurrent();
						} else {
							showStep( steps, i + 1 );
						}
					} ).appendTo( $wrap );
					return $wrap;
				},
			} ).pointer( 'open' );
			current = $el;
			$( '.wctc-pointer .button-primary' ).last().trigger( 'focus' );
		}, 150 );
	}

	function startTour() {
		var steps = tourSteps();
		if ( ! steps.length ) {
			return;
		}
		showStep( steps, 0 );
	}

	$( document ).on( 'keydown', function ( e ) {
		if ( 'Escape' === e.key && current ) {
			closeCurrent();
		}
	} );

	$( function () {
		decorate();
		banner();
		// Variations and order items load after the page; mark them as they arrive.
		var timer = null;
		new MutationObserver( function () {
			window.clearTimeout( timer );
			timer = window.setTimeout( decorate, 200 );
		} ).observe( document.body, { childList: true, subtree: true } );
	} );
}( jQuery ) );
